  SELECT '2026-08-25-france-decret-2026-677', id FROM countries WHERE name_en = 'France';
INSERT INTO story_translations (story_id, lang, title, summary, html)
  VALUES ('2026-08-25-france-decret-2026-677', 'en', 'The last regulatory step lands, five weeks out', 'A décret and arrêté dated 27 July 2026 complete France''s e-invoicing framework: plateforme agréée becomes the single term, the PPF stops being a free send-and-receive route, and DGFiP''s platform list now separates operators who have passed interoperability testing from those who have not.',
          '<h3>🇫🇷 The last regulatory step lands, five weeks out</h3>
<p>France''s regulatory framework for e-invoicing is now complete. A décret and an accompanying arrêté, both dated 27 July 2026, were published in the Journal Officiel on 28 July — the décret carrying the number 2026-677. DGFiP lists both in its own legal-documentation reference for the reform, alongside Article 123 of the Loi de finances 2026 as part of the governing basis.</p>
<p>Reading the analyses published by PwC Avocats and KPMG — the Journal Officiel text itself is behind a barrier we could not open, so this is their reading rather than ours — four changes stand out. The terminology is settled: <em>plateforme agréée</em> (PA) is now the single regulatory term, replacing <em>plateforme de dématérialisation partenaire</em> (PDP). The public portal, the PPF, is repositioned as a directory and data-collection service rather than a route for sending and receiving invoices, which matters to anyone who assumed a free public channel would be available. Platforms face a first surveillance audit within two years of registration, with three months to correct any non-conformity, and AFNOR formats and APIs become binding. And switching platform is now governed: a formal dated and signed agreement, two working days to notify, five for opposition, fifteen for the directory to update — and the outgoing platform must keep receiving on your behalf for twelve months after the transfer.</p>
<p><strong>What this means for your team:</strong> two practical checks. First, if your plan rested on the PPF as a free way to send or receive, that route is gone and you need an accredited platform. Second, DGFiP''s list of platforms — last modified 19 August — is published as <em>two</em> lists, not one: operators that have passed interoperability testing in real conditions, and operators whose file is complete but whose registration is still conditional on passing those tests. Confirm which list your provider appears on, because definitive registration is only granted after the tests are passed. The 1 September date itself is unchanged and was reconfirmed at ministerial level on 11 July.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/france" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full France Deep Dive for complete technical detail →</a></p>');
INSERT INTO story_translations (story_id, lang, title, summary, html)
  VALUES ('2026-08-25-france-decret-2026-677', 'fr', 'La dernière étape réglementaire, à cinq semaines de l''échéance', 'Un décret et un arrêté du 27 juillet 2026 complètent le cadre français : la plateforme agréée devient le terme unique, le PPF cesse d''être une voie gratuite d''émission et de réception, et la liste DGFiP distingue désormais les opérateurs ayant réussi les tests d''interopérabilité de ceux qui les attendent.',
          '<h3>🇫🇷 La dernière étape réglementaire, à cinq semaines de l''échéance</h3>
<p>Le cadre réglementaire français de la facturation électronique est désormais complet. Un décret et un arrêté, tous deux datés du 27 juillet 2026, ont été publiés au Journal officiel le 28 juillet — le décret portant le numéro 2026-677. La DGFiP les recense dans sa propre documentation juridique de référence pour la réforme, aux côtés de l''article 123 de la loi de finances 2026 au titre de la base légale.</p>
<p>À la lecture des analyses publiées par PwC Avocats et KPMG — le texte du Journal officiel lui-même nous est resté inaccessible, il s''agit donc de leur lecture et non de la nôtre — quatre changements ressortent. La terminologie est fixée : la <em>plateforme agréée</em> (PA) devient le terme réglementaire unique et remplace la <em>plateforme de dématérialisation partenaire</em> (PDP). Le portail public, le PPF, est repositionné en annuaire et outil de collecte de données plutôt qu''en voie d''émission et de réception, ce qui compte pour quiconque tablait sur un canal public gratuit. Les plateformes font l''objet d''un premier audit de surveillance dans les deux ans suivant leur immatriculation, avec trois mois pour corriger toute non-conformité, et les formats et API AFNOR deviennent opposables. Enfin, le changement de plateforme est encadré : accord formel daté et signé, deux jours ouvrés pour notifier, cinq pour s''y opposer, quinze pour la mise à jour de l''annuaire — et la plateforme sortante doit continuer à assurer la réception pendant douze mois après le transfert.</p>
<p><strong>Ce que cela implique pour vos équipes :</strong> deux vérifications concrètes. D''abord, si votre plan reposait sur le PPF comme moyen gratuit d''émettre ou de recevoir, cette voie disparaît et il vous faut une plateforme agréée. Ensuite, la liste des plateformes publiée par la DGFiP — modifiée le 19 août — se présente en <em>deux</em> listes et non une : les opérateurs ayant réussi les tests d''interopérabilité en conditions réelles, et ceux dont le dossier est complet mais dont l''immatriculation reste conditionnée à la réussite de ces tests. Vérifiez sur laquelle figure votre prestataire, car l''immatriculation définitive n''est accordée qu''après réussite des tests. La date du 1er septembre, elle, est inchangée et a été reconfirmée au niveau ministériel le 11 juillet.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/france" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full France Deep Dive for complete technical detail →</a></p>');
INSERT INTO story_translations (story_id, lang, title, summary, html)
  VALUES ('2026-08-25-france-decret-2026-677', 'de', 'Der letzte regulatorische Schritt, fünf Wochen vor dem Start', 'Ein Dekret und ein Erlass vom 27. Juli 2026 vervollständigen den französischen Rahmen: „plateforme agréée“ wird zum einzigen Begriff, das PPF ist kein kostenloser Sende- und Empfangsweg mehr, und die DGFiP-Liste trennt nun Betreiber mit bestandenem Interoperabilitätstest von jenen ohne.',
          '<h3>🇫🇷 Der letzte regulatorische Schritt, fünf Wochen vor dem Start</h3>
<p>Frankreichs Regelungsrahmen für die elektronische Rechnungsstellung ist nun vollständig. Ein Dekret und ein begleitender Erlass, beide vom 27. Juli 2026, wurden am 28. Juli im Journal officiel veröffentlicht — das Dekret trägt die Nummer 2026-677. Die DGFiP führt beide in ihrer eigenen juristischen Referenzdokumentation zur Reform auf, neben Artikel 123 des Haushaltsgesetzes 2026 als Teil der Rechtsgrundlage.</p>
<p>Nach den Analysen von PwC Avocats und KPMG — der Text des Journal officiel selbst war für uns nicht zugänglich, es handelt sich also um deren Lesart und nicht um unsere — fallen vier Änderungen auf. Die Terminologie steht fest: <em>plateforme agréée</em> (PA) ist nun der einzige regulatorische Begriff und ersetzt die <em>plateforme de dématérialisation partenaire</em> (PDP). Das öffentliche Portal PPF wird zum Verzeichnis und Datenerhebungsdienst umgewidmet und ist kein Weg mehr zum Senden und Empfangen von Rechnungen — wichtig für alle, die mit einem kostenlosen öffentlichen Kanal gerechnet hatten. Plattformen unterliegen einer ersten Überwachungsprüfung binnen zwei Jahren nach Registrierung, mit drei Monaten zur Behebung von Mängeln, und AFNOR-Formate und -Schnittstellen werden verbindlich. Schließlich ist der Plattformwechsel geregelt: eine formelle, datierte und unterzeichnete Vereinbarung, zwei Werktage zur Anzeige, fünf für den Widerspruch, fünfzehn für die Aktualisierung des Verzeichnisses — und die abgebende Plattform muss den Empfang noch zwölf Monate nach dem Wechsel sicherstellen.</p>
<p><strong>Was das für Ihr Team bedeutet:</strong> zwei konkrete Prüfungen. Erstens: Wenn Ihre Planung auf dem PPF als kostenlosem Sende- oder Empfangsweg beruhte, entfällt dieser Weg und Sie benötigen eine zugelassene Plattform. Zweitens: Die Plattformliste der DGFiP — zuletzt am 19. August geändert — erscheint als <em>zwei</em> Listen, nicht als eine: Betreiber, die die Interoperabilitätstests unter realen Bedingungen bestanden haben, und Betreiber mit vollständiger Akte, deren Registrierung noch vom Bestehen dieser Tests abhängt. Prüfen Sie, auf welcher Liste Ihr Anbieter steht, denn die endgültige Registrierung wird erst nach bestandenem Test erteilt. Der 1. September selbst bleibt unverändert und wurde am 11. Juli auf Ministerebene bestätigt.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/france" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full France Deep Dive for complete technical detail →</a></p>');
INSERT INTO story_translations (story_id, lang, title, summary, html)
  VALUES ('2026-08-25-france-decret-2026-677', 'es', 'El último paso reglamentario, a cinco semanas del arranque', 'Un decreto y una orden de 27 de julio de 2026 completan el marco francés: «plateforme agréée» pasa a ser el término único, el PPF deja de ser una vía gratuita de emisión y recepción, y la lista de la DGFiP separa ya a los operadores que han superado las pruebas de interoperabilidad de los que no.',
          '<h3>🇫🇷 El último paso reglamentario, a cinco semanas del arranque</h3>
<p>El marco reglamentario francés de la facturación electrónica ya está completo. Un decreto y una orden, ambos de 27 de julio de 2026, se publicaron en el Journal officiel el 28 de julio; el decreto lleva el número 2026-677. La DGFiP recoge ambos en su propia documentación jurídica de referencia sobre la reforma, junto al artículo 123 de la ley de presupuestos de 2026 como parte de la base legal.</p>
<p>Según los análisis publicados por PwC Avocats y KPMG —el texto del Journal officiel no nos resultó accesible, de modo que esta es su lectura y no la nuestra— destacan cuatro cambios. La terminología queda fijada: <em>plateforme agréée</em> (PA) pasa a ser el único término reglamentario y sustituye a <em>plateforme de dématérialisation partenaire</em> (PDP). El portal público, el PPF, se reconvierte en directorio y herramienta de recogida de datos en lugar de vía de emisión y recepción, lo que importa a quien contase con un canal público gratuito. Las plataformas se someten a una primera auditoría de supervisión en los dos años siguientes a su registro, con tres meses para corregir cualquier disconformidad, y los formatos y API de AFNOR pasan a ser vinculantes. Por último, el cambio de plataforma queda regulado: acuerdo formal fechado y firmado, dos días hábiles para notificar, cinco para oponerse, quince para actualizar el directorio, y la plataforma saliente debe seguir prestando el servicio de recepción durante doce meses tras el traspaso.</p>
<p><strong>Qué significa para su equipo:</strong> dos comprobaciones prácticas. Primera: si su plan se apoyaba en el PPF como vía gratuita para emitir o recibir, esa vía desaparece y necesitará una plataforma acreditada. Segunda: la lista de plataformas de la DGFiP —modificada por última vez el 19 de agosto— se publica como <em>dos</em> listas, no como una: los operadores que han superado las pruebas de interoperabilidad en condiciones reales y aquellos cuyo expediente está completo pero cuyo registro sigue condicionado a superarlas. Confirme en cuál figura su proveedor, porque el registro definitivo solo se concede tras superar las pruebas. La fecha del 1 de septiembre no ha cambiado y se reconfirmó a nivel ministerial el 11 de julio.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/france" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full France Deep Dive for complete technical detail →</a></p>');

-- ---- 2026-08-25-hungary-receipt-data-operational-detail ----
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published)
  VALUES ('2026-08-25-hungary-receipt-data-operational-detail', '2026-08-25', '2026-08', 'Roughly 270,000 Hungarian taxpayers must report receipt data within three calendar days — weekends included — from 1 September. NAV has published the KOBAK walkthrough and a v1.0 machine interface, and has said it will not fine before 2027.',
          '<h3>🇭🇺 Receipt-data reporting: what actually has to happen from 1 September</h3>
<p>Hungary''s receipt-data obligation starts on 1 September 2026, and the operational detail is now published. It reaches businesses that issue receipts by hand from a receipt book, produce them from software on paper, or issue them electronically — a population WTS Klient puts at roughly 270,000 taxpayers, explicitly including webshops, event organisers, accommodation providers and medical and educational services. Businesses already using an online cash register need do nothing: their reporting happens automatically.</p>
<p>The clock is the part worth circling. Receipt data is due within three <em>calendar</em> days of issue, aggregated per day and broken down by tax rate — weekends and public holidays count, so a receipt issued on Friday is due by Monday midnight. There are three ways to file: NAV''s free ePénztárgép application, manual entry through the KOBAK portal, or a machine interface whose specification reached version 1.0 on NAV''s public GitHub repository on 13 July, with an XSD and a developer discussion forum alongside it. NAV published a step-by-step walkthrough of the KOBAK screens in early August; note that if you produce receipts from software, you must register the software''s name before you can record anything. One exemption is worth knowing: receipts issued by hand <em>because</em> a cash register has failed or operations are temporarily disrupted fall outside the obligation.</p>
<p><strong>What this means for your team:</strong> NAV has said it will not impose default penalties between 1 September and 31 December 2026, treating the period as a supported transition, with fines possible from 1 January 2027 — up to HUF 400,000 for an individual and HUF 1,000,000 for an organisation, and repeatable. Worth being precise about what that is: NAV has announced it, and we found no legislative instrument creating it, so treat it as administrative forbearance rather than a statutory amnesty. The obligation itself starts on 1 September either way, and the three-day clock starts running with it.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/hungary" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full Hungary Deep Dive for complete technical detail →</a></p>',
          'https://nav.gov.hu/ado/enyugta/nyugtaadat-szolgaltatas/kezi-rogzites/segedlet-a-kobak-portal-nyugtaadat-rogzito-feluletenek-hasznalatahoz', 1);
INSERT INTO story_countries (story_id, country_id)
  SELECT '2026-08-25-hungary-receipt-data-operational-detail', id FROM countries WHERE name_en = 'Hungary';
INSERT INTO story_translations (story_id, lang, title, summary, html)
  VALUES ('2026-08-25-hungary-receipt-data-operational-detail', 'en', 'Receipt-data reporting: what actually has to happen from 1 September', 'Roughly 270,000 Hungarian taxpayers must report receipt data within three calendar days — weekends included — from 1 September. NAV has published the KOBAK walkthrough and a v1.0 machine interface, and has said it will not fine before 2027.',
          '<h3>🇭🇺 Receipt-data reporting: what actually has to happen from 1 September</h3>
<p>Hungary''s receipt-data obligation starts on 1 September 2026, and the operational detail is now published. It reaches businesses that issue receipts by hand from a receipt book, produce them from software on paper, or issue them electronically — a population WTS Klient puts at roughly 270,000 taxpayers, explicitly including webshops, event organisers, accommodation providers and medical and educational services. Businesses already using an online cash register need do nothing: their reporting happens automatically.</p>
<p>The clock is the part worth circling. Receipt data is due within three <em>calendar</em> days of issue, aggregated per day and broken down by tax rate — weekends and public holidays count, so a receipt issued on Friday is due by Monday midnight. There are three ways to file: NAV''s free ePénztárgép application, manual entry through the KOBAK portal, or a machine interface whose specification reached version 1.0 on NAV''s public GitHub repository on 13 July, with an XSD and a developer discussion forum alongside it. NAV published a step-by-step walkthrough of the KOBAK screens in early August; note that if you produce receipts from software, you must register the software''s name before you can record anything. One exemption is worth knowing: receipts issued by hand <em>because</em> a cash register has failed or operations are temporarily disrupted fall outside the obligation.</p>
<p><strong>What this means for your team:</strong> NAV has said it will not impose default penalties between 1 September and 31 December 2026, treating the period as a supported transition, with fines possible from 1 January 2027 — up to HUF 400,000 for an individual and HUF 1,000,000 for an organisation, and repeatable. Worth being precise about what that is: NAV has announced it, and we found no legislative instrument creating it, so treat it as administrative forbearance rather than a statutory amnesty. The obligation itself starts on 1 September either way, and the three-day clock starts running with it.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/hungary" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full Hungary Deep Dive for complete technical detail →</a></p>');
INSERT INTO story_translations (story_id, lang, title, summary, html)
  VALUES ('2026-08-25-hungary-receipt-data-operational-detail', 'fr', 'Données de tickets : ce qu''il faudra réellement faire à partir du 1er septembre', 'Environ 270 000 contribuables hongrois devront transmettre les données de tickets sous trois jours calendaires — week-ends compris — à compter du 1er septembre. Le NAV a publié le guide du portail KOBAK et une interface machine en version 1.0, et annonce qu''il ne sanctionnera pas avant 2027.',
          '<h3>🇭🇺 Données de tickets : ce qu''il faudra réellement faire à partir du 1er septembre</h3>
<p>L''obligation hongroise de transmission des données de tickets démarre le 1er septembre 2026, et le détail opérationnel est désormais publié. Elle vise les entreprises qui émettent des tickets à la main depuis un carnet, les produisent sur papier depuis un logiciel ou les délivrent sous forme électronique — une population que WTS Klient évalue à quelque 270 000 contribuables, incluant explicitement les boutiques en ligne, les organisateurs d''événements, les hébergeurs et les prestataires médicaux et éducatifs. Les entreprises déjà équipées d''une caisse enregistreuse en ligne n''ont rien à faire : leur transmission est automatique.</p>
<p>Le délai est le point à retenir. Les données doivent être transmises dans les trois jours <em>calendaires</em> suivant l''émission, agrégées par jour et ventilées par taux de TVA — les week-ends et jours fériés comptent, de sorte qu''un ticket émis le vendredi est dû le lundi à minuit. Trois voies sont possibles : l''application gratuite ePénztárgép du NAV, la saisie manuelle via le portail KOBAK, ou une interface machine dont la spécification a atteint la version 1.0 sur le dépôt GitHub public du NAV le 13 juillet, accompagnée d''un XSD et d''un forum pour les développeurs. Le NAV a publié début août un guide pas à pas des écrans KOBAK ; à noter, si vous produisez vos tickets depuis un logiciel, vous devez d''abord enregistrer le nom de ce logiciel. Une exemption mérite d''être connue : les tickets émis à la main <em>parce que</em> la caisse est en panne ou l''exploitation temporairement perturbée sortent du champ de l''obligation.</p>
<p><strong>Ce que cela implique pour vos équipes :</strong> le NAV a annoncé qu''il n''appliquerait pas de sanction pour manquement entre le 1er septembre et le 31 décembre 2026, traitant cette période comme une transition accompagnée, les amendes devenant possibles à compter du 1er janvier 2027 — jusqu''à 400 000 HUF pour une personne physique et 1 000 000 HUF pour une organisation, et renouvelables. Soyons précis sur la nature de cette mesure : le NAV l''a annoncée, et nous n''avons trouvé aucun texte législatif l''instituant ; il faut donc y voir une tolérance administrative et non une amnistie légale. L''obligation, elle, commence le 1er septembre dans tous les cas, et le délai de trois jours court avec elle.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/hungary" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full Hungary Deep Dive for complete technical detail →</a></p>');
INSERT INTO story_translations (story_id, lang, title, summary, html)
  VALUES ('2026-08-25-hungary-receipt-data-operational-detail', 'de', 'Belegdatenmeldung: was ab dem 1. September tatsächlich zu tun ist', 'Rund 270.000 ungarische Steuerpflichtige müssen Belegdaten ab dem 1. September binnen drei Kalendertagen melden — Wochenenden eingeschlossen. Die NAV hat die KOBAK-Anleitung und eine Maschinenschnittstelle in Version 1.0 veröffentlicht und angekündigt, vor 2027 nicht zu sanktionieren.',
          '<h3>🇭🇺 Belegdatenmeldung: was ab dem 1. September tatsächlich zu tun ist</h3>
<p>Die ungarische Belegdatenpflicht beginnt am 1. September 2026, und die operativen Einzelheiten liegen nun vor. Betroffen sind Unternehmen, die Belege handschriftlich aus einem Belegblock ausstellen, sie per Software auf Papier erzeugen oder elektronisch ausgeben — eine Gruppe, die WTS Klient auf rund 270.000 Steuerpflichtige beziffert, ausdrücklich einschließlich Webshops, Veranstaltern, Beherbergungsbetrieben sowie medizinischen und Bildungsdienstleistern. Unternehmen mit einer Online-Registrierkasse müssen nichts tun: Ihre Meldung erfolgt automatisch.</p>
<p>Die Frist ist der entscheidende Punkt. Belegdaten sind binnen drei <em>Kalendertagen</em> nach Ausstellung zu melden, tagesweise aggregiert und nach Steuersatz aufgeschlüsselt — Wochenenden und Feiertage zählen mit, ein am Freitag ausgestellter Beleg ist also bis Montag um Mitternacht fällig. Es gibt drei Wege: die kostenlose NAV-Anwendung ePénztárgép, die manuelle Erfassung über das KOBAK-Portal oder eine Maschinenschnittstelle, deren Spezifikation am 13. Juli im öffentlichen GitHub-Repository der NAV die Version 1.0 erreichte, samt XSD und Entwicklerforum. Anfang August veröffentlichte die NAV eine Schritt-für-Schritt-Anleitung zu den KOBAK-Masken; wer Belege per Software erzeugt, muss zunächst den Namen dieser Software registrieren. Eine Ausnahme ist wissenswert: Belege, die handschriftlich ausgestellt werden, <em>weil</em> eine Registrierkasse ausgefallen oder der Betrieb vorübergehend gestört ist, fallen nicht unter die Pflicht.</p>
<p><strong>Was das für Ihr Team bedeutet:</strong> Die NAV hat erklärt, zwischen dem 1. September und dem 31. Dezember 2026 keine Versäumnisstrafen zu verhängen und diesen Zeitraum als begleiteten Übergang zu behandeln; Bußgelder sind ab dem 1. Januar 2027 möglich — bis zu 400.000 HUF für natürliche Personen und 1.000.000 HUF für Organisationen, wiederholbar. Dabei lohnt Genauigkeit: Die NAV hat dies angekündigt, und wir haben keinen Rechtsakt gefunden, der es begründet; es ist daher als behördliche Nachsicht zu verstehen, nicht als gesetzliche Amnestie. Die Pflicht selbst beginnt in jedem Fall am 1. September, und die Dreitagesfrist läuft mit ihr an.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/hungary" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full Hungary Deep Dive for complete technical detail →</a></p>');
INSERT INTO story_translations (story_id, lang, title, summary, html)
  VALUES ('2026-08-25-hungary-receipt-data-operational-detail', 'es', 'Datos de tiques: qué habrá que hacer realmente desde el 1 de septiembre', 'Unos 270.000 contribuyentes húngaros deberán comunicar los datos de los tiques en tres días naturales —fines de semana incluidos— desde el 1 de septiembre. La NAV ha publicado la guía del portal KOBAK y una interfaz de máquina en versión 1.0, y afirma que no sancionará antes de 2027.',
          '<h3>🇭🇺 Datos de tiques: qué habrá que hacer realmente desde el 1 de septiembre</h3>
<p>La obligación húngara de comunicar los datos de los tiques arranca el 1 de septiembre de 2026 y el detalle operativo ya está publicado. Alcanza a las empresas que expiden tiques a mano desde un talonario, los generan en papel desde un programa o los emiten en formato electrónico: un colectivo que WTS Klient cifra en unos 270.000 contribuyentes, incluidas expresamente las tiendas en línea, los organizadores de eventos, los alojamientos y los prestadores sanitarios y educativos. Las empresas que ya usan una caja registradora en línea no tienen que hacer nada: su comunicación es automática.</p>
<p>El plazo es lo que conviene subrayar. Los datos deben transmitirse en un plazo de tres días <em>naturales</em> desde la expedición, agregados por día y desglosados por tipo impositivo; los fines de semana y festivos cuentan, de modo que un tique emitido el viernes vence el lunes a medianoche. Hay tres vías: la aplicación gratuita ePénztárgép de la NAV, el registro manual en el portal KOBAK, o una interfaz de máquina cuya especificación alcanzó la versión 1.0 en el repositorio público de GitHub de la NAV el 13 de julio, con su XSD y un foro para desarrolladores. A principios de agosto la NAV publicó una guía paso a paso de las pantallas de KOBAK; conviene saber que, si genera los tiques desde un programa, primero debe registrar el nombre de ese programa. Una exención merece atención: los tiques expedidos a mano <em>porque</em> la caja ha fallado o la actividad está temporalmente alterada quedan fuera de la obligación.</p>
<p><strong>Qué significa para su equipo:</strong> la NAV ha manifestado que no impondrá sanciones por incumplimiento entre el 1 de septiembre y el 31 de diciembre de 2026, tratando ese periodo como una transición acompañada, y que las multas serán posibles desde el 1 de enero de 2027: hasta 400.000 HUF para personas físicas y 1.000.000 HUF para organizaciones, y reiterables. Conviene ser precisos sobre qué es esto: lo ha anunciado la NAV y no hemos encontrado ningún instrumento legislativo que lo establezca, así que debe entenderse como tolerancia administrativa y no como una amnistía legal. La obligación en sí comienza el 1 de septiembre en cualquier caso, y con ella empieza a correr el plazo de tres días.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/hungary" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full Hungary Deep Dive for complete technical detail →</a></p>');

